
select a.PEDIDO,a.TOT_QTDE_ORIGINAL,a.ERP_TOTAL_QTD_DISTRIB,a.ERP_PERCENT_DISTRIB,a.ERP_TOTAL_CAIXAS_ORIGINAL, b.qtde,
CAST( (a.TOT_QTDE_ORIGINAL/b.QTDE) as INT) AS TOT_CAIXAS,
CAST( (a.TOT_QTDE_ORIGINAL/b.QTDE)*0.7 as INT)  AS TOT_CAIXAS_70
from compras a 
inner join CAEDU_COMPRAS_PRODUTOS_PACKS_TOTAL b on b.pedido = a.pedido
where a.pedido in 
('147740','147761','147765','147766','150888','150889','151461','151473','151690','153006','153238','153239','153240','153241','153762','153763',
'153764','153765','153766','153767','153768','153769','153770','153789','154405','154432','155891','156253','156255','156353','156356','156358',
'156365','156366','156391','156392','156394','156397','156403','156438','156446','156969','157030','157595','158278')


